mapper.select:
SELECT cleanup_id, object_name, attempts
FROM storage_cleanup_task
WHERE next_attempt_at <= #{now}
ORDER BY next_attempt_at ASC, cleanup_id ASC
LIMIT #{limit}

mapper.update:
UPDATE storage_cleanup_task
SET attempts=attempts+1, next_attempt_at=#{nextAttemptAt}, last_error=#{lastError}
WHERE cleanup_id=#{cleanupId}
